INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7338068, 1146711, 30982, '<td valign="top">Excellent kid''s eye view.  I can only imagine what the youngster in the hat has done to earn such a face from the young woman with the bow.  But the young man with the glasses is there to provide reassurance.  Nice story.</td>', 'Excellent kid''s eye view.  I can only imagine what the youngster in the hat has done to earn such a face from the young woman with the bow.  But the young man with the glasses is there to provide reassurance.  Nice story.', '2015-04-06 01:26:43.000000', NULL, 1),
(7338071, 1146708, 30982, '<td valign="top">A ghost has passed between them - I think perhap the dog has noticed.  The human, perhaps not.</td>', 'A ghost has passed between them - I think perhap the dog has noticed.  The human, perhaps not.', '2015-04-06 01:28:38.000000', NULL, 1),
(7338073, 1145715, 30982, '<td valign="top">Delightfully busy and chaotic!</td>', 'Delightfully busy and chaotic!', '2015-04-06 01:29:13.000000', NULL, 1),
(7338076, 1146484, 30982, '<td valign="top">Almost a Japanese watercolor.  Well seen!</td>', 'Almost a Japanese watercolor.  Well seen!', '2015-04-06 01:29:57.000000', NULL, 1),
(7338078, 1146435, 30982, '<td valign="top">Outstanding moment in time.</td>', 'Outstanding moment in time.', '2015-04-06 01:30:46.000000', NULL, 1),
(7338080, 1146577, 30982, '<td valign="top">This made me smile.  Your supervisor is so very intent on his job, and perhaps just a bit worried that the lines have fallen.  Obviously there''s a problem, given there''s a truck parked beyond the barrier.</td>', 'This made me smile.  Your supervisor is so very intent on his job, and perhaps just a bit worried that the lines have fallen.  Obviously there''s a problem, given there''s a truck parked beyond the barrier.', '2015-04-06 01:32:09.000000', NULL, 1),
(7338082, 1146588, 30982, '<td valign="top">A beautiful dichotom.</td>', 'A beautiful dichotom.', '2015-04-06 01:33:29.000000', NULL, 1),
(7338093, 1146484, 83313, '<td valign="top">I don''t know what he will actually make of this, but I think it would make a great piece to frame and hang.</td>', 'I don''t know what he will actually make of this, but I think it would make a great piece to frame and hang.', '2015-04-06 01:41:52.000000', NULL, 1),
(7338107, 1146564, 16241, '<td valign="top">Precisely!</td>', 'Precisely!', '2015-04-06 04:05:42.000000', NULL, 1),
(7338174, 1146587, 30364, '<td valign="top">It''s the kind of gloomy thing I often produce myself, so I''m pretty much obliged to like it :)<br/>My favourite touch is of course the PULL label: it''s a different (and more interesting) kind of leading line!<br/>Also nice to see a vignette. Many people consider them passé but I remain a determined fan.  Of course, I like Nina Simone too so I''m kinda passé myself.  Thank you.</td>', 'It''s the kind of gloomy thing I often produce myself, so I''m pretty much obliged to like it :)My favourite touch is of course the PULL label: it''s a different (and more interesting) kind of leading line!Also nice to see a vignette. Many people consider them passé but I remain a determined fan.  Of course, I like Nina Simone too so I''m kinda passé myself.  Thank you.', '2015-04-06 08:19:44.000000', NULL, 1),
(7338176, 1146249, 30364, '<td valign="top">Looks a bit like Jimi Hendrix at Woodstock.  So now I hear the Star Spangled Banned being ripped to shreds on a Stratocaster.  Actually, now that mention it, I also see Jimi is trailing the Stars and Stripes like a matador.  Bet you wish now you''d thought of something else!  But I don''t because I like it.  Beautiful tones drifting with the blurred movement.  Thank you.</td>', 'Looks a bit like Jimi Hendrix at Woodstock.  So now I hear the Star Spangled Banned being ripped to shreds on a Stratocaster.  Actually, now that mention it, I also see Jimi is trailing the Stars and Stripes like a matador.  Bet you wish now you''d thought of something else!  But I don''t because I like it.  Beautiful tones drifting with the blurred movement.  Thank you.', '2015-04-06 08:24:02.000000', NULL, 1),
(7338177, 1146531, 30364, '<td valign="top">Not my personal cup of tea perhaps, but I refer only to the gently bucolic subject matter.  The photography however is excellent, with far better handling of a challenging tonal range than I can ever manage.  Thank you.</td>', 'Not my personal cup of tea perhaps, but I refer only to the gently bucolic subject matter.  The photography however is excellent, with far better handling of a challenging tonal range than I can ever manage.  Thank you.', '2015-04-06 08:26:30.000000', NULL, 1),
(7338178, 1145910, 30364, '<td valign="top">Texting, listening to music, ripping up the roadway, and no eyes for the approaching garbage truck (I merely assume the truck, but it seems inevitable really): that''s a free radical''s philosophy I can relate to!  I like the deep blacks and the savage vignette.  Thank you.</td>', 'Texting, listening to music, ripping up the roadway, and no eyes for the approaching garbage truck (I merely assume the truck, but it seems inevitable really): that''s a free radical''s philosophy I can relate to!  I like the deep blacks and the savage vignette.  Thank you.', '2015-04-06 08:30:51.000000', NULL, 1),
(7338180, 1146543, 30364, '<td valign="top">I''m always happy to see a radical crop and in this case it''s not just the up-and-down but the side-to-side too.  That hovering front foot and its shadow is also a nice touch.  And the implied wheat field.  And ... did you really mean this ... the yellow brick road!!!  ''Course you meant it!  Lots of sly delights in this deceptively simple picture.  Thank you.</td>', 'I''m always happy to see a radical crop and in this case it''s not just the up-and-down but the side-to-side too.  That hovering front foot and its shadow is also a nice touch.  And the implied wheat field.  And ... did you really mean this ... the yellow brick road!!!  ''Course you meant it!  Lots of sly delights in this deceptively simple picture.  Thank you.', '2015-04-06 08:35:42.000000', NULL, 1),
(7338182, 1146222, 30364, '<td valign="top">Love that it''s not all in focus.  I''ve tried to figure out what it is; it must be an assemblage of parts as it makes no mechanical sense as presented.  Some kind of precision mount?  It looks a bit like my knee joints feel first thing in the morning.  I enjoyed trying to put it together (pardon the pun).  Thank you.</td>', 'Love that it''s not all in focus.  I''ve tried to figure out what it is; it must be an assemblage of parts as it makes no mechanical sense as presented.  Some kind of precision mount?  It looks a bit like my knee joints feel first thing in the morning.  I enjoyed trying to put it together (pardon the pun).  Thank you.', '2015-04-06 08:40:13.000000', NULL, 1),
(7338185, 1146298, 30364, '<td valign="top">Crikey!  I have no idea. Let''s see ...One big blob looks a bit like a map of Alaska, so the bright light must be the North Star, seen from the other side.  Thus you are obviously an astronaut.  So you see, your cunning plan came to nothing. Thank you.</td>', 'Crikey!  I have no idea. Let''s see ...One big blob looks a bit like a map of Alaska, so the bright light must be the North Star, seen from the other side.  Thus you are obviously an astronaut.  So you see, your cunning plan came to nothing. Thank you.', '2015-04-06 08:43:43.000000', NULL, 1),
(7338186, 1146444, 30364, '<td valign="top">Red tassel stands for good luck, does it not?  So I wish you good luck.  I like the beautiful tones in and around the Buddha; very apt and pleasing.  Thank you.</td>', 'Red tassel stands for good luck, does it not?  So I wish you good luck.  I like the beautiful tones in and around the Buddha; very apt and pleasing.  Thank you.', '2015-04-06 08:46:14.000000', NULL, 1),
(7338187, 1146628, 30364, '<td valign="top">Aw, come on ... this is too hard for me.  What I see is a tiny mechanical alien, pulsing out some kind of energy field.  And he seems to be poking his tongue out at me.  A wise reaction, probably.  Lots of fun puzzling fruitlessly over this.  Thank you.</td>', 'Aw, come on ... this is too hard for me.  What I see is a tiny mechanical alien, pulsing out some kind of energy field.  And he seems to be poking his tongue out at me.  A wise reaction, probably.  Lots of fun puzzling fruitlessly over this.  Thank you.', '2015-04-06 08:48:54.000000', NULL, 1),
(7338188, 1146580, 30364, '<td valign="top">The texture, the shadows and the beautiful tones all appeal to me very much.  The withered flowers (roses?) are bordering on saccharine, but justified and thus saved on the right side of that border.  But the ribbon is maybe a bridge too far.  On the other hand, better a bridge too far than one too few, and anyway that''s the whole point of the picture.  It''s not really a photograph that I''d rave about from a conceptual point of view, but it''s beautifully executed; even a hack like me can see that.  Thank you.</td>', 'The texture, the shadows and the beautiful tones all appeal to me very much.  The withered flowers (roses?) are bordering on saccharine, but justified and thus saved on the right side of that border.  But the ribbon is maybe a bridge too far.  On the other hand, better a bridge too far than one too few, and anyway that''s the whole point of the picture.  It''s not really a photograph that I''d rave about from a conceptual point of view, but it''s beautifully executed; even a hack like me can see that.  Thank you.', '2015-04-06 08:58:23.000000', NULL, 1),
(7338189, 1146354, 30364, '<td valign="top">It''s a weird picture, so you sure got that right!  Those glowing eyes are creepy; another plus!  And I always enjoy theatrical contrasts of light (or in this case the absence of light).  Unusual, interesting.  Thank you.</td>', 'It''s a weird picture, so you sure got that right!  Those glowing eyes are creepy; another plus!  And I always enjoy theatrical contrasts of light (or in this case the absence of light).  Unusual, interesting.  Thank you.', '2015-04-06 09:01:15.000000', NULL, 1),
(7338190, 1146361, 30364, '<td valign="top">Very nice tones.  And a lovely, cosseting vignette with blur.  Always a favourite combination of mine.  Thank you.</td>', 'Very nice tones.  And a lovely, cosseting vignette with blur.  Always a favourite combination of mine.  Thank you.', '2015-04-06 09:03:58.000000', NULL, 1),
(7338191, 1146636, 30364, '<td valign="top">The interest for me is trying to figure out the provenance of the jawbone.  A deer, maybe?  I hope you will reveal all later?  Thank you.</td>', 'The interest for me is trying to figure out the provenance of the jawbone.  A deer, maybe?  I hope you will reveal all later?  Thank you.', '2015-04-06 09:06:11.000000', NULL, 1),
(7338192, 1146240, 30364, '<td valign="top">Interesting crop, and lovely tones; blues, yellows.  Am I allowed to say, "Nice rack"?  Better not, I suppose.  Anyway, it''s definitely not a boring photograph: thank you!</td>', 'Interesting crop, and lovely tones; blues, yellows.  Am I allowed to say, "Nice rack"?  Better not, I suppose.  Anyway, it''s definitely not a boring photograph: thank you!', '2015-04-06 09:08:57.000000', NULL, 1),
(7338194, 1146434, 30364, '<td valign="top">I''m not big on insects (although they probably think I am; sorry, awful joke).  But this is lovely.  It''s odd how a picture that normally demands colour can be so interesting, in a different way, when done mono.  Not all the time, of course, but now and then it''s a welcome change of pace.  And this one is.  Thank you.</td>', 'I''m not big on insects (although they probably think I am; sorry, awful joke).  But this is lovely.  It''s odd how a picture that normally demands colour can be so interesting, in a different way, when done mono.  Not all the time, of course, but now and then it''s a welcome change of pace.  And this one is.  Thank you.', '2015-04-06 09:12:23.000000', NULL, 1),
(7338195, 1146057, 30364, '<td valign="top">I''m not going there.  But thank you anyway.</td>', 'I''m not going there.  But thank you anyway.', '2015-04-06 09:13:27.000000', NULL, 1),
(7338197, 1146714, 30364, '<td valign="top">This can''t be real, but it does look Weegee-ish so well done you.  Why not real?  Surely cop1 is not going to be cuffing a guy who has a pistol within easy grasp of his free hand?  And surely cop2 will, if he fires that silly assault rifle at that range, be likely to splash a bit of collateral damage into cop1?  On the other hand, these could be Cory''s New Mexico cops, in which case any madness is possible.  But whatever, it is interesting, so for that I thank you.</td>', 'This can''t be real, but it does look Weegee-ish so well done you.  Why not real?  Surely cop1 is not going to be cuffing a guy who has a pistol within easy grasp of his free hand?  And surely cop2 will, if he fires that silly assault rifle at that range, be likely to splash a bit of collateral damage into cop1?  On the other hand, these could be Cory''s New Mexico cops, in which case any madness is possible.  But whatever, it is interesting, so for that I thank you.', '2015-04-06 09:22:44.000000', NULL, 1),
(7338200, 1146720, 30364, '<td valign="top">This isn''t my thing ( I mean photographically), but that''s my problem and not yours.  The pool''s very clean though, and I do admire that.  I don''t mean to be flippant, by the way ... I simply do not like photographs in this style and I can''t think of anything to say that softens that cruel judgement.  Oh ... yes I can; lots more people will like it than will like the kind of gloomy rubbish that I produce, so at least I can say you''re on the right track and I''m not.  Thank you.</td>', 'This isn''t my thing ( I mean photographically), but that''s my problem and not yours.  The pool''s very clean though, and I do admire that.  I don''t mean to be flippant, by the way ... I simply do not like photographs in this style and I can''t think of anything to say that softens that cruel judgement.  Oh ... yes I can; lots more people will like it than will like the kind of gloomy rubbish that I produce, so at least I can say you''re on the right track and I''m not.  Thank you.', '2015-04-06 09:31:39.000000', NULL, 1),
(7338203, 1145883, 30364, '<td valign="top">I just don''t enjoy botanical photographs, but having said that this one is more interesting than most because of the buds rather than strident flowers.  Seems more reflective, somehow.  Thank you.</td>', 'I just don''t enjoy botanical photographs, but having said that this one is more interesting than most because of the buds rather than strident flowers.  Seems more reflective, somehow.  Thank you.', '2015-04-06 09:33:29.000000', NULL, 1),
(7338204, 1146370, 30364, '<td valign="top">It''s quite striking.  I have no idea if it''s a good moon picture or not, because I know nothing about such matters.  For me, pointing a camera up means I''m trying to get the battery out.  It appears a good likeness, though.  Very nicely lit, and I suspect you used only natural light, too.  Thank you.</td>', 'It''s quite striking.  I have no idea if it''s a good moon picture or not, because I know nothing about such matters.  For me, pointing a camera up means I''m trying to get the battery out.  It appears a good likeness, though.  Very nicely lit, and I suspect you used only natural light, too.  Thank you.', '2015-04-06 09:37:41.000000', NULL, 1),
(7338206, 1146690, 30364, '<td valign="top">Clever.  I always wondered how to pronounce it.  And now I know.  Thank you.  Alternatively, <i>gratias tibi ago.</i></td>', 'Clever.  I always wondered how to pronounce it.  And now I know.  Thank you.  Alternatively, gratias tibi ago.', '2015-04-06 09:41:46.000000', NULL, 1),
(7338208, 1146233, 30364, '<td valign="top">The title grates a bit, but the uppermost bird saves the day for me; I''m always in favour of an arbitrary looking crop.  Whole thing looks like a mobile, which is also good.  Thank you.</td>', 'The title grates a bit, but the uppermost bird saves the day for me; I''m always in favour of an arbitrary looking crop.  Whole thing looks like a mobile, which is also good.  Thank you.', '2015-04-06 09:44:16.000000', NULL, 1),
(7338210, 1146648, 30364, '<td valign="top">It''s an unfortunate juxtaposition, isn''t it?  And so surprising that it''s one so often seen.  These sign people must surely do it on purpose.  Although I''m a fan of vignettes, or even a slave to them alas, in this case I''d have resisted.  Not sure why, it just seems unwarranted here.  Maybe a case of over-egging the pudding?  Thank you.</td>', 'It''s an unfortunate juxtaposition, isn''t it?  And so surprising that it''s one so often seen.  These sign people must surely do it on purpose.  Although I''m a fan of vignettes, or even a slave to them alas, in this case I''d have resisted.  Not sure why, it just seems unwarranted here.  Maybe a case of over-egging the pudding?  Thank you.', '2015-04-06 09:47:57.000000', NULL, 1),
(7338212, 1146467, 30364, '<td valign="top">Always like a good wildlife shot, especially when it''s an environmental shot like this and not a super close-up that might have been taken in a zoo.  Hope you identify the deer species in your notes, because these are not in my neighbourhood crew.  And I appreciated the reference in the title; you''re very gracious! Thank you.</td>', 'Always like a good wildlife shot, especially when it''s an environmental shot like this and not a super close-up that might have been taken in a zoo.  Hope you identify the deer species in your notes, because these are not in my neighbourhood crew.  And I appreciated the reference in the title; you''re very gracious! Thank you.', '2015-04-06 09:50:40.000000', NULL, 1),
(7338213, 1146473, 63398, '<td valign="top">A shot I could easily see coming from Paul. The backstory of the song is heart-wrenching and meaningful, especially for us older DPCers. Nice presentation and allusion with the shadow. My top choice in the challenge.</td>', 'A shot I could easily see coming from Paul. The backstory of the song is heart-wrenching and meaningful, especially for us older DPCers. Nice presentation and allusion with the shadow. My top choice in the challenge.', '2015-04-06 09:53:43.000000', NULL, 1),
(7338214, 1146586, 63398, '<td valign="top">Technically proficient.......MOST pleasing viscerally, and quite thought provoking. Truly with the philosophy. One of my Top 3 picks.</td>', 'Technically proficient.......MOST pleasing viscerally, and quite thought provoking. Truly with the philosophy. One of my Top 3 picks.', '2015-04-06 09:55:02.000000', NULL, 1),
(7338219, 1146648, 63398, '<td valign="top">I love the irony......terrific find. Well selected for this challenge. I like the PP, too. One of my Top 3 picks.</td>', 'I love the irony......terrific find. Well selected for this challenge. I like the PP, too. One of my Top 3 picks.', '2015-04-06 10:14:00.000000', NULL, 1),
(7338220, 1146435, 63398, '<td valign="top">Nice double entendre! Terrifically engaging image. One of my top picks.</td>', 'Nice double entendre! Terrifically engaging image. One of my top picks.', '2015-04-06 10:15:18.000000', NULL, 1),
(7338222, 1146054, 63398, '<td valign="top">Really terrific find! Well shot &amp; processed.......a great one for this challenge. One of my top picks.</td>', 'Really terrific find! Well shot & processed.......a great one for this challenge. One of my top picks.', '2015-04-06 10:16:14.000000', NULL, 1),
(7338224, 1146371, 16148, '<td valign="top">Beautiful image with wonderful light.  The textures in the painting on the glass really pop in b&amp;w.  Would work well in color too, I imagine.</td>', 'Beautiful image with wonderful light.  The textures in the painting on the glass really pop in b&w.  Would work well in color too, I imagine.', '2015-04-06 10:20:08.000000', NULL, 1),
(7338225, 1146719, 63398, '<td valign="top">Well done. I like it that you''ve used Paul''s own words in this. Certainly this one cannot merit spanking.</td>', 'Well done. I like it that you''ve used Paul''s own words in this. Certainly this one cannot merit spanking.', '2015-04-06 10:21:23.000000', NULL, 1),
(7338228, 1146712, 63398, '<td valign="top">An intriguing image.....I do like the post-processing and composition as well as the way this image makes me want to know more.Well done</td>', 'An intriguing image.....I do like the post-processing and composition as well as the way this image makes me want to know more.Well done', '2015-04-06 10:28:40.000000', NULL, 1),
(7338229, 1146528, 16148, '<td valign="top">Not sure the heavy vignette was needed but I do like this image.  That little cloud creeping in the right side holds everything together.</td>', 'Not sure the heavy vignette was needed but I do like this image.  That little cloud creeping in the right side holds everything together.', '2015-04-06 10:28:55.000000', NULL, 1),
(7338234, 1146703, 63398, '<td valign="top">Great mood......I love the capture of the obvious interaction. The soft focus adds to the intrigue of the image and I like the harsh light for the image as well.</td>', 'Great mood......I love the capture of the obvious interaction. The soft focus adds to the intrigue of the image and I like the harsh light for the image as well.', '2015-04-06 10:35:49.000000', NULL, 1),
(7338235, 1146476, 16148, '<td valign="top">I like how the darkness leads to a small bright section, implied ending, on top.  Almost there!</td>', 'I like how the darkness leads to a small bright section, implied ending, on top.  Almost there!', '2015-04-06 10:35:53.000000', NULL, 1),
(7338236, 1146458, 16148, '<td valign="top">Wonderful story telling!</td>', 'Wonderful story telling!', '2015-04-06 10:36:47.000000', NULL, 1),
(7338248, 1146436, 118154, '<td valign="top">I  have enjoyed looking at this for some time now. No doubt I will be back.</td>', 'I  have enjoyed looking at this for some time now. No doubt I will be back.', '2015-04-06 10:59:23.000000', NULL, 1),
(7338249, 1146629, 63398, '<td valign="top">Good fortune to have caught this! Nicely titled to work for this challenge. I like the generally busy tone to the scene.</td>', 'Good fortune to have caught this! Nicely titled to work for this challenge. I like the generally busy tone to the scene.', '2015-04-06 11:00:09.000000', NULL, 1),
(7338250, 1146239, 118154, '<td valign="top">Something here that really grabs my attention, top ten for me.</td>', 'Something here that really grabs my attention, top ten for me.', '2015-04-06 11:00:22.000000', NULL, 1),
(7338251, 1146105, 118154, '<td valign="top">Love the threat of this,in my top ten for sure.</td>', 'Love the threat of this,in my top ten for sure.', '2015-04-06 11:01:00.000000', NULL, 1),
(7338252, 1145853, 63398, '<td valign="top">Nicely haunting &amp; evocative. Well suited to the challenge.</td>', 'Nicely haunting & evocative. Well suited to the challenge.', '2015-04-06 11:01:08.000000', NULL, 1),
(7338253, 1146370, 118154, '<td valign="top">This really does nothing for me at all. I will give about 3.</td>', 'This really does nothing for me at all. I will give about 3.', '2015-04-06 11:02:51.000000', NULL, 1),
(7338282, 1146712, 108069, '<td valign="top">Great photo. Very well seen. Quirky, fun, pareidolia-ish, and a great capture of textures, lines and gradients that wash out. Title couldn''t be better. I''d hang it on my wall and I bet Ubique''ll love it.</td>', 'Great photo. Very well seen. Quirky, fun, pareidolia-ish, and a great capture of textures, lines and gradients that wash out. Title couldn''t be better. I''d hang it on my wall and I bet Ubique''ll love it.', '2015-04-06 12:32:06.000000', NULL, 1),
(7338283, 1146288, 108069, '<td valign="top">Certainly Ubique-ish from his safari collection. Nice capture.</td>', 'Certainly Ubique-ish from his safari collection. Nice capture.', '2015-04-06 12:32:52.000000', NULL, 1),
(7338285, 1146628, 108069, '<td valign="top">A head-scratcher. My eyes are pinpoint focused on the detail in little orb and the rest of the photo (80%?) is completely irrelevant, as designed. It''s an interesting twist on use of space.</td>', 'A head-scratcher. My eyes are pinpoint focused on the detail in little orb and the rest of the photo (80%?) is completely irrelevant, as designed. It''s an interesting twist on use of space.', '2015-04-06 12:35:58.000000', NULL, 1),
(7338302, 1146704, 179608, '<td valign="top">Hyper-real and endearing...<br/>I love this subject; the perfection should have had a best light but it remains one of the best entry</td>', 'Hyper-real and endearing...I love this subject; the perfection should have had a best light but it remains one of the best entry', '2015-04-06 13:29:29.000000', NULL, 1),
(7338303, 1146634, 179608, '<td valign="top">Beautiful coupling for the yellow colour; I don''t like the widw space around the subjects but is always one of the best for this challenge</td>', 'Beautiful coupling for the yellow colour; I don''t like the widw space around the subjects but is always one of the best for this challenge', '2015-04-06 13:31:21.000000', NULL, 1),
(7338306, 1146720, 179608, '<td valign="top">Ethereal...suspended in a sort of magic liquid<br/>Good done</td>', 'Ethereal...suspended in a sort of magic liquidGood done', '2015-04-06 13:33:02.000000', NULL, 1),
(7338317, 1146435, 30364, '<td valign="top">Well I adore Oscar Wilde, so big plus.  And beer, so another plus.  B&amp;W; yet plussier!  Grain?  Check.  Pretty girl in the beer delivery business?  Plussier and plussier.  You can hardly tick any more of my personal boxes.<br/> <br/>I also like the photograph anyway because it''s the kind of unfinished, or unresolved, snapshot that makes me hug my camera.  Who is being favoured with that lovely smile?  How much will he tip?  <br/> <br/>Honestly, I love this stuff because it''s the one way that our real lives can be elevated as a sort of casual art.<br/> <br/>You did good, and I thank you.</td>', 'Well I adore Oscar Wilde, so big plus.  And beer, so another plus.  B&W; yet plussier!  Grain?  Check.  Pretty girl in the beer delivery business?  Plussier and plussier.  You can hardly tick any more of my personal boxes. I also like the photograph anyway because it''s the kind of unfinished, or unresolved, snapshot that makes me hug my camera.  Who is being favoured with that lovely smile?  How much will he tip?   Honestly, I love this stuff because it''s the one way that our real lives can be elevated as a sort of casual art. You did good, and I thank you.', '2015-04-06 14:01:58.000000', NULL, 1),
(7338336, 1146586, 30364, '<td valign="top">It''s so weird.  I figured it out, and enjoyed the journey.  I don''t imagine that the picture will feature on any calendars or cake tins, but that''s a good thing too.  And the title?  Freakin'' awesome, because it dares the viewer to do a double take.  WTF is the balloon about?  That''s the question with no answer, and yet the balloon is the point.<br/> <br/>Most of all I enjoyed the picture because it turns perception upside down, without being too arty about it.<br/> <br/>Interesting?  You bet!  Thank you.</td>', 'It''s so weird.  I figured it out, and enjoyed the journey.  I don''t imagine that the picture will feature on any calendars or cake tins, but that''s a good thing too.  And the title?  Freakin'' awesome, because it dares the viewer to do a double take.  WTF is the balloon about?  That''s the question with no answer, and yet the balloon is the point. Most of all I enjoyed the picture because it turns perception upside down, without being too arty about it. Interesting?  You bet!  Thank you.', '2015-04-06 14:07:26.000000', NULL, 1),
(7338349, 1146239, 30364, '<td valign="top">Wildly matter-of-fact, no artifice.  It is what it is, and what it is is real.  The world''s a better place for photographic doodles like this.  How can the viewer not engage with it?  I can''t resist.  Thank you.</td>', 'Wildly matter-of-fact, no artifice.  It is what it is, and what it is is real.  The world''s a better place for photographic doodles like this.  How can the viewer not engage with it?  I can''t resist.  Thank you.', '2015-04-06 14:10:33.000000', NULL, 1),
(7338361, 1145715, 30364, '<td valign="top">I did a shot like this long ago, except I could not afford the extravagant cast.  I had just one guy.  There''s something theatrical about zebra crossings (or whatever they may be called where you live); it''s like improvisational theatre, but en masse. The picture is packed with interesting little playlets; especially love the tight rank of suits about one-third from the left.  And the big circular drain at lower right, ready to transport new players in and out of the stage; like a theatre trapdoor.  Great fun.  Thank you.</td>', 'I did a shot like this long ago, except I could not afford the extravagant cast.  I had just one guy.  There''s something theatrical about zebra crossings (or whatever they may be called where you live); it''s like improvisational theatre, but en masse. The picture is packed with interesting little playlets; especially love the tight rank of suits about one-third from the left.  And the big circular drain at lower right, ready to transport new players in and out of the stage; like a theatre trapdoor.  Great fun.  Thank you.', '2015-04-06 14:16:03.000000', NULL, 1),
(7338380, 1146719, 30364, '<td valign="top">My immediate (literally instantaneous) thought has purged all other possible interpretations from my mind ... the guy looks <i>exactly</i> like Colin Hay.  He was once World Famous in Australia for the song <i>Down Under</i> which includes the fabulous line, "Where women glow and men plunder", to say nothing of, "He just smiled and gave me a Vegemite sandwich".  Perhaps you need to be Australian to get the delicate nuance.  It''s awfully subtle.<br/> <br/>The cat, on the other hand, doesn''t look like any of the heroes of my youth.  Lucky cat.<br/> <br/>The picture is weird and inexplicable, so that stacks up in your favour.<br/> <br/>Interesting?  ''Course it is!  Vegemite, Colin Hay, mystery cat; what more could you want?  Thank you.</td>', 'My immediate (literally instantaneous) thought has purged all other possible interpretations from my mind ... the guy looks exactly like Colin Hay.  He was once World Famous in Australia for the song Down Under which includes the fabulous line, "Where women glow and men plunder", to say nothing of, "He just smiled and gave me a Vegemite sandwich".  Perhaps you need to be Australian to get the delicate nuance.  It''s awfully subtle. The cat, on the other hand, doesn''t look like any of the heroes of my youth.  Lucky cat. The picture is weird and inexplicable, so that stacks up in your favour. Interesting?  ''Course it is!  Vegemite, Colin Hay, mystery cat; what more could you want?  Thank you.', '2015-04-06 14:26:07.000000', NULL, 1),
(7338386, 1146629, 30364, '<td valign="top">I like street and happy juxtapositions are the meat and potatoes of street.  So I like this; it''s not fancy, but it''s nourishing.  Thank you.</td>', 'I like street and happy juxtapositions are the meat and potatoes of street.  So I like this; it''s not fancy, but it''s nourishing.  Thank you.', '2015-04-06 14:27:47.000000', NULL, 1),
(7338389, 1145853, 30364, '<td valign="top">The kind of baffling nonsense that I''m always pleased to give several minutes'' worth of idle consideration.  I never get anywhere, but it''s still time well spent.  It''s forlorn and somehow a bit sad, which I think was your own impulse.  And it''s certainly interesting, in a not-really-interesting kind of way.  Hard to ask more than that! Thank you.</td>', 'The kind of baffling nonsense that I''m always pleased to give several minutes'' worth of idle consideration.  I never get anywhere, but it''s still time well spent.  It''s forlorn and somehow a bit sad, which I think was your own impulse.  And it''s certainly interesting, in a not-really-interesting kind of way.  Hard to ask more than that! Thank you.', '2015-04-06 14:31:45.000000', NULL, 1),
(7338391, 1146371, 30364, '<td valign="top">Nice portrait and a very interesting (i.e. novel) idea.  And cleverly executed too.  Thank you.</td>', 'Nice portrait and a very interesting (i.e. novel) idea.  And cleverly executed too.  Thank you.', '2015-04-06 14:32:39.000000', NULL, 1),
(7338399, 1146600, 30364, '<td valign="top">Tools, crap colour, negligent exposure and an inexplicable party hat: you''ve certainly got my attention.  Thank you.</td>', 'Tools, crap colour, negligent exposure and an inexplicable party hat: you''ve certainly got my attention.  Thank you.', '2015-04-06 14:34:18.000000', NULL, 1),
(7338416, 1146704, 30364, '<td valign="top">Holy smoke, this is a puzzle.  The title should, I have a nagging suspicion, mean something to me, but it does not.  The spinal segment is also baffling (but quite beautifully lit &amp; photographed).  I have no idea what it means, and that always leaves me happily curious.  Thank you.</td>', 'Holy smoke, this is a puzzle.  The title should, I have a nagging suspicion, mean something to me, but it does not.  The spinal segment is also baffling (but quite beautifully lit & photographed).  I have no idea what it means, and that always leaves me happily curious.  Thank you.', '2015-04-06 14:38:01.000000', NULL, 1),
(7338421, 1146461, 30364, '<td valign="top">Yes, but the alternative is sitting right next to trash.  So it''s a utilitarian compromise, I suppose.  Give a little to get a little.  Composition is elegantly simple, balance is perfect.  Than you.</td>', 'Yes, but the alternative is sitting right next to trash.  So it''s a utilitarian compromise, I suppose.  Give a little to get a little.  Composition is elegantly simple, balance is perfect.  Than you.', '2015-04-06 14:41:48.000000', NULL, 1),
(7338451, 1145746, 179769, '<td valign="top">Whew....I really feel the drama here!   Neat!</td>', 'Whew....I really feel the drama here!   Neat!', '2015-04-06 15:21:39.000000', NULL, 1),
(7338456, 1146628, 50695, '<td valign="top">For me, the best thing about this photo is that you''ve entered it in a "ubique" challenge. If this were a free study I wouldn''t give it a second look. But in a "ubique" challenge it is very strange indeed. Like a little alien spaceship entering ubique''s world, where surely it is in great danger. It might be stepped on by an elephant, or devastating smirked at.<br/> <br/>I wonder if you''re playing with the idea of "photo as object"</td>', 'For me, the best thing about this photo is that you''ve entered it in a "ubique" challenge. If this were a free study I wouldn''t give it a second look. But in a "ubique" challenge it is very strange indeed. Like a little alien spaceship entering ubique''s world, where surely it is in great danger. It might be stepped on by an elephant, or devastating smirked at. I wonder if you''re playing with the idea of "photo as object"', '2015-04-06 15:24:35.000000', NULL, 1),
(7338457, 1146591, 50695, '<td valign="top">appropriate for this challenge. the lack of subject and disorienting angle, the strong obscuring shadows, all suggest that the photo itself is the object... not a pointer to objects.</td>', 'appropriate for this challenge. the lack of subject and disorienting angle, the strong obscuring shadows, all suggest that the photo itself is the object... not a pointer to objects.', '2015-04-06 15:25:52.000000', NULL, 1),
