(7339237, 1146476, 30982, '<td valign="top">Love it!  The eyes are worth a million bucks.</td>', 'Love it!  The eyes are worth a million bucks.', '2015-04-08 00:37:02.000000', NULL, 1),
(7339238, 1145910, 30982, '<td valign="top">Tuned in or tuned out?  Getting harder and harder to get pictures of people not staring at their hand-held devices.</td>', 'Tuned in or tuned out?  Getting harder and harder to get pictures of people not staring at their hand-held devices.', '2015-04-08 00:40:31.000000', NULL, 1),
(7339286, 1146370, 30982, '<td valign="top">A good moon shot - harder to do than it looks (I''ve tried, I suck at it).</td>', 'A good moon shot - harder to do than it looks (I''ve tried, I suck at it).', '2015-04-08 02:13:53.000000', NULL, 1),
(7339287, 1146586, 30982, '<td valign="top">It''s the tip of the iceberg kinda thing.  That lovely touch of pink really brings it home.</td>', 'It''s the tip of the iceberg kinda thing.  That lovely touch of pink really brings it home.', '2015-04-08 02:14:36.000000', NULL, 1),
(7339288, 1146444, 30982, '<td valign="top">Definitely intriguing!</td>', 'Definitely intriguing!', '2015-04-08 02:14:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7339289, 1146587, 30982, '<td valign="top">Fascinating and a bit of a conundrum.  Is the car inside?  Why?  How does PULL fit into the equation?  OK, really I just happen to like the picture.</td>', 'Fascinating and a bit of a conundrum.  Is the car inside?  Why?  How does PULL fit into the equation?  OK, really I just happen to like the picture.', '2015-04-08 02:16:42.000000', NULL, 1),
(7339290, 1146658, 30982, '<td valign="top">This is just SO cool!!!!  What a wonderful keepsake for all involved!</td>', 'This is just SO cool!!!!  What a wonderful keepsake for all involved!', '2015-04-08 02:17:03.000000', NULL, 1),
(7339291, 1146490, 30982, '<td valign="top">Excellent perspective.  There''s a strange imbalance/interplay between the guy staring down and sthe sunlit space beyond.  This ties together well in spite of that.</td>', 'Excellent perspective.  There''s a strange imbalance/interplay between the guy staring down and sthe sunlit space beyond.  This ties together well in spite of that.', '2015-04-08 02:18:16.000000', NULL, 1),
(7339292, 1145865, 30982, '<td valign="top">What a sad looking dog.  I like the faded, almost painterly effect.</td>', 'What a sad looking dog.  I like the faded, almost painterly effect.', '2015-04-08 02:19:04.000000', NULL, 1),
(7339293, 1146271, 30982, '<td valign="top">Nice collection of shadows, lines, textures.</td>', 'Nice collection of shadows, lines, textures.', '2015-04-08 02:19:20.000000', NULL, 1),
(7339294, 1146648, 30982, '<td valign="top">Ha!!  Very well seen.  And of course you put a cemetary at the end of a dead end road.... makes perfect sense.  Now as to why some get buried on the hillside and some get fenced in... well, that one just has to wonder about.</td>', 'Ha!!  Very well seen.  And of course you put a cemetary at the end of a dead end road.... makes perfect sense.  Now as to why some get buried on the hillside and some get fenced in... well, that one just has to wonder about.', '2015-04-08 02:20:08.000000', NULL, 1),
(7339295, 1146591, 30982, '<td valign="top">Great title, love the harsh shadows and the grays, and the ripples in the water add natural texture.  All works well together.</td>', 'Great title, love the harsh shadows and the grays, and the ripples in the water add natural texture.  All works well together.', '2015-04-08 02:21:23.000000', NULL, 1),
(7339296, 1146457, 30982, '<td valign="top">Fancy-pants title!  No idea what it means, but I like the artistic approach to the photograph.  Feels almost metallic.</td>', 'Fancy-pants title!  No idea what it means, but I like the artistic approach to the photograph.  Feels almost metallic.', '2015-04-08 02:22:15.000000', NULL, 1),
(7339297, 1146662, 30982, '<td valign="top">The sum of the parts is a whole bird.  Nifty approach to the subject!</td>', 'The sum of the parts is a whole bird.  Nifty approach to the subject!', '2015-04-08 02:22:38.000000', NULL, 1),
(7339298, 1146626, 30982, '<td valign="top">Brings back memories.  In college, the girls would stand on one side of the room, the boys on the other, and we''d sing this song back and forth.  Beer was usually involved.  In large quantities.  This is a great shot.  Not as far as classic pretty-pixel photography - in that sense it''s kinda eh - but as far as an encapsulated memory (and an old one at that) this rocks.</td>', 'Brings back memories.  In college, the girls would stand on one side of the room, the boys on the other, and we''d sing this song back and forth.  Beer was usually involved.  In large quantities.  This is a great shot.  Not as far as classic pretty-pixel photography - in that sense it''s kinda eh - but as far as an encapsulated memory (and an old one at that) this rocks.', '2015-04-08 02:23:59.000000', NULL, 1),
(7339299, 1146714, 30982, '<td valign="top">I''m hoping this is staged because that one gun is still far too close to the gent who''s being handcuffed.  And I gotta think they''d not be very thrilled about you being close enough to shoot with a flash.  But then again, I just make up stories to go with the pictures sometimes...</td>', 'I''m hoping this is staged because that one gun is still far too close to the gent who''s being handcuffed.  And I gotta think they''d not be very thrilled about you being close enough to shoot with a flash.  But then again, I just make up stories to go with the pictures sometimes...', '2015-04-08 02:25:42.000000', NULL, 1),
(7339300, 1146222, 30982, '<td valign="top">Oddly stockish for a ubique-philosophy based challenge; the detail is lovely!</td>', 'Oddly stockish for a ubique-philosophy based challenge; the detail is lovely!', '2015-04-08 02:26:18.000000', NULL, 1),
(7339301, 1145810, 30982, '<td valign="top">AND a seagull.  Beautifully seen!</td>', 'AND a seagull.  Beautifully seen!', '2015-04-08 02:26:48.000000', NULL, 1),
(7339308, 1146458, 30982, '<td valign="top">Life begins at 60, huh?  The guy behind bars may not agree.  Such delightful randomness!</td>', 'Life begins at 60, huh?  The guy behind bars may not agree.  Such delightful randomness!', '2015-04-08 02:36:57.000000', NULL, 1),
(7339365, 1146620, 30364, '<td valign="top">Crikey!  When I first looked I thought they were humongous fangs!  It''s a satisfyingly weird photograph, with all the negligent nonsense I love: brutal vignette, extravagant blur, and the transformative effect of making something benign look instead like a nightmare.  You''ve got the touch!  Thank you.</td>', 'Crikey!  When I first looked I thought they were humongous fangs!  It''s a satisfyingly weird photograph, with all the negligent nonsense I love: brutal vignette, extravagant blur, and the transformative effect of making something benign look instead like a nightmare.  You''ve got the touch!  Thank you.', '2015-04-08 05:09:07.000000', NULL, 1),
(7339367, 1146364, 30364, '<td valign="top">You''ve celebrated one of my favourite things: a photograph about The Photograph.  You''ve also composed it perfectly and handled the challenging tonal range with great skill.  But that technical stuff is for me all subordinate to the main theme, which is "What is a photograph? Why do we take photographs?  What do they mean?"  I just love all that philosophical stuff. Thank you.</td>', 'You''ve celebrated one of my favourite things: a photograph about The Photograph.  You''ve also composed it perfectly and handled the challenging tonal range with great skill.  But that technical stuff is for me all subordinate to the main theme, which is "What is a photograph? Why do we take photographs?  What do they mean?"  I just love all that philosophical stuff. Thank you.', '2015-04-08 05:13:53.000000', NULL, 1),
(7339368, 1146652, 30364, '<td valign="top">Dark and negligent.  Grain.  Wild crop.  Open-closed composition. Uncertain story.  These are a few of my favourite things!  Thank you.</td>', 'Dark and negligent.  Grain.  Wild crop.  Open-closed composition. Uncertain story.  These are a few of my favourite things!  Thank you.', '2015-04-08 05:16:30.000000', NULL, 1),
(7339372, 1146436, 30364, '<td valign="top">I''m a sucker for improbable shots like this, where every ''serious'' photographic consideration is set aside in the interests of the moment.  But the greatest pleasure from this kind of shot is the spontaneous reactions of the players; the range of facial expressions among the four facing camera is fabulous ... everything from (reading left to right) delight; to mild and self-conscious amusement; to scepticism; to whatever the guy on right is doing (conducting the bird?)  This kind of photography don''t mean nothin''; and is all the more delightful for that.  Thank you.</td>', 'I''m a sucker for improbable shots like this, where every ''serious'' photographic consideration is set aside in the interests of the moment.  But the greatest pleasure from this kind of shot is the spontaneous reactions of the players; the range of facial expressions among the four facing camera is fabulous ... everything from (reading left to right) delight; to mild and self-conscious amusement; to scepticism; to whatever the guy on right is doing (conducting the bird?)  This kind of photography don''t mean nothin''; and is all the more delightful for that.  Thank you.', '2015-04-08 05:24:20.000000', NULL, 1),
(7339373, 1146105, 30364, '<td valign="top">Just beautiful tones, and bubbling with spontaneity.  The photograph at first looks like a negligent snapshot, but even if that''s what you tried to do I''m afraid that your commitment to your craft showed through.  There''s too much skill and instinctive judgement evident here for you to get away with pretending that you don''t care.  A lovely living photograph: fun for hacks like me, but also instructive for more serious photographers.  You''re pretty good.  Thank you.</td>', 'Just beautiful tones, and bubbling with spontaneity.  The photograph at first looks like a negligent snapshot, but even if that''s what you tried to do I''m afraid that your commitment to your craft showed through.  There''s too much skill and instinctive judgement evident here for you to get away with pretending that you don''t care.  A lovely living photograph: fun for hacks like me, but also instructive for more serious photographers.  You''re pretty good.  Thank you.', '2015-04-08 05:30:21.000000', NULL, 1),
(7339378, 1146591, 30364, '<td valign="top">Nicely negligent, deliciously disorienting.  I take one of these unintentionally nearly every time I try to take my little camera out of my pocket, and I often like it better than the picture I was actually about to take.  Thank you.</td>', 'Nicely negligent, deliciously disorienting.  I take one of these unintentionally nearly every time I try to take my little camera out of my pocket, and I often like it better than the picture I was actually about to take.  Thank you.', '2015-04-08 05:35:59.000000', NULL, 1),
(7339381, 1146271, 30364, '<td valign="top">I never tire of this kind of photograph because it shows something that you can''t see properly with actual eyes.  The eyes automatically ''correct'' the exposure as your gaze drifts, thus draining all the drama out of the contrasts ... it''s rendered by the eyes like a musical chord.  But the camera fixes it as a raw-edged, howling single note; something like BB King would play.  And so less is more, same as it ever was.  Love the dramatic shapes too; wavering between abstract and material.  Terrific, interesting photograph.  Thank you.</td>', 'I never tire of this kind of photograph because it shows something that you can''t see properly with actual eyes.  The eyes automatically ''correct'' the exposure as your gaze drifts, thus draining all the drama out of the contrasts ... it''s rendered by the eyes like a musical chord.  But the camera fixes it as a raw-edged, howling single note; something like BB King would play.  And so less is more, same as it ever was.  Love the dramatic shapes too; wavering between abstract and material.  Terrific, interesting photograph.  Thank you.', '2015-04-08 05:45:22.000000', NULL, 1),
(7339382, 1146705, 30364, '<td valign="top">It''s nice to see ducks in a context less travelled.  I''m well sick of pictures of them bobbing about in the water like ... like ducks, so this is a welcome little excursion.  And the backlight is very nice too; gives them individual character with just a few strokes, like a good sketch.  Thank you.</td>', 'It''s nice to see ducks in a context less travelled.  I''m well sick of pictures of them bobbing about in the water like ... like ducks, so this is a welcome little excursion.  And the backlight is very nice too; gives them individual character with just a few strokes, like a good sketch.  Thank you.', '2015-04-08 05:48:33.000000', NULL, 1),
(7339383, 1146660, 30364, '<td valign="top">Lovely tones!  This is like a lith print, and the thing I love about those is that you can appreciate them with equal satisfaction (though for different reasons) from up real close or from far away.  It''s a mural AND an etching.  Most pictures aren''t like that.  The bird is delightfully niched too.  Thank you.</td>', 'Lovely tones!  This is like a lith print, and the thing I love about those is that you can appreciate them with equal satisfaction (though for different reasons) from up real close or from far away.  It''s a mural AND an etching.  Most pictures aren''t like that.  The bird is delightfully niched too.  Thank you.', '2015-04-08 05:51:47.000000', NULL, 1),
(7339384, 1146168, 30364, '<td valign="top">I love football, and I love savage and unconventional crops, so this is my speed indeed.  But if he''s about to take a penalty kick, he''s cheating.  Unless there''s six goalkeepers, of course.  Good fun.  Thank you.</td>', 'I love football, and I love savage and unconventional crops, so this is my speed indeed.  But if he''s about to take a penalty kick, he''s cheating.  Unless there''s six goalkeepers, of course.  Good fun.  Thank you.', '2015-04-08 05:53:55.000000', NULL, 1),
(7339385, 1146403, 30364, '<td valign="top">This reminds me of something striped.  Big kick out of the unconventional crop, and the brutal vignette is ... brutal (always happy to see gratuitous brutality, photographically speaking).  Thank you.</td>', 'This reminds me of something striped.  Big kick out of the unconventional crop, and the brutal vignette is ... brutal (always happy to see gratuitous brutality, photographically speaking).  Thank you.', '2015-04-08 05:57:05.000000', NULL, 1),
(7339387, 1146403, 100393, '<td valign="top">Night of the bovine! I like how we are communing with them. Excellent tones too.<br/> <br/>I like how you aren''t afraid of the shadows.</td>', 'Night of the bovine! I like how we are communing with them. Excellent tones too. I like how you aren''t afraid of the shadows.', '2015-04-08 06:36:13.000000', NULL, 1),
(7339388, 1145910, 100393, '<td valign="top">Nicely done - great sense of freedom and of cool crisp air. I enjoy the tilt, it communicates an in-the-moment feel.</td>', 'Nicely done - great sense of freedom and of cool crisp air. I enjoy the tilt, it communicates an in-the-moment feel.', '2015-04-08 06:37:23.000000', NULL, 1),
(7339390, 1146361, 30214, '<td valign="top">great anachronism, fingers are straight out of 1930s, and the camera... you know</td>', 'great anachronism, fingers are straight out of 1930s, and the camera... you know', '2015-04-08 06:38:22.000000', NULL, 1),
(7339391, 1146135, 100393, '<td valign="top">Nearly brilliant. Fabulous scene, great face but for me the quality of the image doesn''t live up to what you have captured. It may not bother the man himself, but for a gear head like me... (A decent 6 nonetheless).</td>', 'Nearly brilliant. Fabulous scene, great face but for me the quality of the image doesn''t live up to what you have captured. It may not bother the man himself, but for a gear head like me... (A decent 6 nonetheless).', '2015-04-08 06:38:55.000000', NULL, 1),
(7339392, 1146620, 30214, '<td valign="top">interesting gaze, I can sense his apprehension</td>', 'interesting gaze, I can sense his apprehension', '2015-04-08 06:39:18.000000', NULL, 1),
(7339393, 1146710, 30214, '<td valign="top">nice framing, and I like the contrast between females on the right</td>', 'nice framing, and I like the contrast between females on the right', '2015-04-08 06:40:25.000000', NULL, 1),
(7339394, 1145715, 100393, '<td valign="top">Bang! That''s the contrast smacking me in the face.<br/> <br/>Great starkness to go with the busyness of the scene.</td>', 'Bang! That''s the contrast smacking me in the face. Great starkness to go with the busyness of the scene.', '2015-04-08 06:40:39.000000', NULL, 1),
(7339395, 1146704, 30214, '<td valign="top">technically nicely done</td>', 'technically nicely done', '2015-04-08 06:41:25.000000', NULL, 1),
(7339396, 1146461, 100393, '<td valign="top">A lonely seat and your title steers me to an irony that  wouldn''t have picked up on without your help. I''m liking the dynamic range here.</td>', 'A lonely seat and your title steers me to an irony that  wouldn''t have picked up on without your help. I''m liking the dynamic range here.', '2015-04-08 06:41:48.000000', NULL, 1),
(7339398, 1146463, 100393, '<td valign="top">Gorgeous colours, I love the double yellow transecting the scene. I like the red at the top too.<br/> <br/>I''m less keen on the cars on the left, a curious inclusion for me.<br/> <br/>It''s a great scene, well-captured though.</td>', 'Gorgeous colours, I love the double yellow transecting the scene. I like the red at the top too. I''m less keen on the cars on the left, a curious inclusion for me. It''s a great scene, well-captured though.', '2015-04-08 06:43:20.000000', NULL, 1),
(7339399, 1146403, 30214, '<td valign="top">love the tones. I can see here across between two great Ubique''s photos, zebras and a horseback</td>', 'love the tones. I can see here across between two great Ubique''s photos, zebras and a horseback', '2015-04-08 06:43:25.000000', NULL, 1),
(7339400, 1146703, 100393, '<td valign="top">Bags of story and an eclectic edit. What''s not to like. Blur two ways too - and it doesn''t hurt a bit. I like how engaging this is - bumping to a 7.</td>', 'Bags of story and an eclectic edit. What''s not to like. Blur two ways too - and it doesn''t hurt a bit. I like how engaging this is - bumping to a 7.', '2015-04-08 06:44:20.000000', NULL, 1),
(7339401, 1145714, 30214, '<td valign="top">great POV, makes the photo very dynamic</td>', 'great POV, makes the photo very dynamic', '2015-04-08 06:44:48.000000', NULL, 1),
(7339402, 1146711, 100393, '<td valign="top">Like a sibling smite in progress. Great drama. I like how we are sharing their journeying stroll.</td>', 'Like a sibling smite in progress. Great drama. I like how we are sharing their journeying stroll.', '2015-04-08 06:45:25.000000', NULL, 1),
(7339403, 1145853, 100393, '<td valign="top">A constructed piece - there is an occasional delight in the contrived. I like how the dark right hand side is reminiscent of a shutter curtain.<br/> <br/>Lovely light.</td>', 'A constructed piece - there is an occasional delight in the contrived. I like how the dark right hand side is reminiscent of a shutter curtain. Lovely light.', '2015-04-08 06:46:27.000000', NULL, 1),
(7339404, 1146370, 100393, '<td valign="top">A fine picture of the moon. A bit straight-up for me but this is technically good enough for me to enjoy the moon with new (and borrowed) eyes.</td>', 'A fine picture of the moon. A bit straight-up for me but this is technically good enough for me to enjoy the moon with new (and borrowed) eyes.', '2015-04-08 06:47:38.000000', NULL, 1),
(7339405, 1146158, 100393, '<td valign="top">The juxtaposition of smooth water and textured feather is very effective.</td>', 'The juxtaposition of smooth water and textured feather is very effective.', '2015-04-08 06:48:10.000000', NULL, 1),
(7339406, 1146288, 100393, '<td valign="top">I like the subject nod and the toning is perfect.</td>', 'I like the subject nod and the toning is perfect.', '2015-04-08 06:48:33.000000', NULL, 1),
(7339407, 1146476, 100393, '<td valign="top">This is a lovely portrait with bags of humanity, simultaneously isolating your subject while literally communicating a back story. Bumping to a 7.</td>', 'This is a lovely portrait with bags of humanity, simultaneously isolating your subject while literally communicating a back story. Bumping to a 7.', '2015-04-08 06:49:27.000000', NULL, 1),
(7339408, 1146460, 100393, '<td valign="top">Over-egged eyes aside, I love the intensity here. The wetness is palpable.</td>', 'Over-egged eyes aside, I love the intensity here. The wetness is palpable.', '2015-04-08 06:50:07.000000', NULL, 1),
(7339409, 1146471, 100393, '<td valign="top">A curious collection of subjects but well balanced and intriguing. Perhaps it''s my macabre imagination but I can''t help thinking something is going on here that is in violation of human rights - like an out-of-shot interrogation.</td>', 'A curious collection of subjects but well balanced and intriguing. Perhaps it''s my macabre imagination but I can''t help thinking something is going on here that is in violation of human rights - like an out-of-shot interrogation.', '2015-04-08 06:52:28.000000', NULL, 1),
(7339410, 1146586, 100393, '<td valign="top">Interesting POV. The balloon certainly adds interest but the clash of colours jars. Perhaps that is the intent here?</td>', 'Interesting POV. The balloon certainly adds interest but the clash of colours jars. Perhaps that is the intent here?', '2015-04-08 06:53:37.000000', NULL, 1),
(7339411, 1146434, 100393, '<td valign="top">I really enjoy busy bokeh. Your tones elevate this insect shot.</td>', 'I really enjoy busy bokeh. Your tones elevate this insect shot.', '2015-04-08 06:54:11.000000', NULL, 1),
(7339413, 1145714, 100393, '<td valign="top">An unlikely getaway - I hear the engine gunning. Will her ''Clyde'' make it to the car?<br/> <br/>I enjoyed the implicit invitation to create a story here.</td>', 'An unlikely getaway - I hear the engine gunning. Will her ''Clyde'' make it to the car? I enjoyed the implicit invitation to create a story here.', '2015-04-08 06:55:43.000000', NULL, 1),
(7339414, 1146457, 100393, '<td valign="top">This is my commenting pass having voted earlier - I much prefer this on this subsequent visit. Corroded metal meets causal water. Very well constructed. Bumping to a 7.</td>', 'This is my commenting pass having voted earlier - I much prefer this on this subsequent visit. Corroded metal meets causal water. Very well constructed. Bumping to a 7.', '2015-04-08 06:57:44.000000', NULL, 1),
(7339415, 1146712, 100393, '<td valign="top">I like how prominent the vertical texture is. I can''t look at it without my eye being drawn downwards. The limited colour palette is very effective too.</td>', 'I like how prominent the vertical texture is. I can''t look at it without my eye being drawn downwards. The limited colour palette is very effective too.', '2015-04-08 06:58:48.000000', NULL, 1),
(7339418, 1146658, 100393, '<td valign="top">Very endearing portrait, I''m not sure about the soft rendition or the blur vignette, but there is no denying the power of this slice of human story.</td>', 'Very endearing portrait, I''m not sure about the soft rendition or the blur vignette, but there is no denying the power of this slice of human story.', '2015-04-08 07:00:53.000000', NULL, 1),
(7339419, 1146704, 100393, '<td valign="top">Despite knowing human spinal anatomy pretty well, it''s not helping me orientate myself around this creature''s back. I like how you''ve made me sit and stare.</td>', 'Despite knowing human spinal anatomy pretty well, it''s not helping me orientate myself around this creature''s back. I like how you''ve made me sit and stare.', '2015-04-08 07:04:13.000000', NULL, 1),
(7339420, 1146463, 30214, '<td valign="top">nice colors and interesting composition. Actually, the tide is quite cheerful, but these black cars (which look almost like hearses) on the left provide an ominous counterpoint.</td>', 'nice colors and interesting composition. Actually, the tide is quite cheerful, but these black cars (which look almost like hearses) on the left provide an ominous counterpoint.', '2015-04-08 07:05:18.000000', NULL, 1),
(7339421, 1146600, 100393, '<td valign="top">You''ve transported me to my garage as I search for that particular spanner I know I have. And so I get ambushed by a memory. Evocative.</td>', 'You''ve transported me to my garage as I search for that particular spanner I know I have. And so I get ambushed by a memory. Evocative.', '2015-04-08 07:05:37.000000', NULL, 1),
(7339422, 1146580, 100393, '<td valign="top">Precisely composed, I really enjoy the shadow. I''m a fan of glow, whether lens of software induced, but here (perhaps because of the ribbon) it jars a little rather than soothes.<br/> <br/>Fabulous light.</td>', 'Precisely composed, I really enjoy the shadow. I''m a fan of glow, whether lens of software induced, but here (perhaps because of the ribbon) it jars a little rather than soothes. Fabulous light.', '2015-04-08 07:07:05.000000', NULL, 1),
(7339423, 1146534, 30214, '<td valign="top">beautiful contrast. this could be ubique if it was not so flawless ))</td>', 'beautiful contrast. this could be ubique if it was not so flawless ))', '2015-04-08 07:07:07.000000', NULL, 1),
(7339424, 1146240, 100393, '<td valign="top">I enjoy the split tones, the detail and the transecting crop. Nice light too.</td>', 'I enjoy the split tones, the detail and the transecting crop. Nice light too.', '2015-04-08 07:07:57.000000', NULL, 1),
(7339425, 1146233, 100393, '<td valign="top">Still and dynamic, black and white. Some nice contrasts here.</td>', 'Still and dynamic, black and white. Some nice contrasts here.', '2015-04-08 07:08:46.000000', NULL, 1),
(7339426, 1146626, 100393, '<td valign="top">Bold, with a delightful title. I''m being trained with your eye for detail.</td>', 'Bold, with a delightful title. I''m being trained with your eye for detail.', '2015-04-08 07:09:32.000000', NULL, 1),
(7339427, 1145712, 100393, '<td valign="top">An electric whisk in the bedroom. Emancipated.<br/> <br/>I think this is an image that challenge the viewer to discern too deeply while it revels in its own intended frivolity.</td>', 'An electric whisk in the bedroom. Emancipated. I think this is an image that challenge the viewer to discern too deeply while it revels in its own intended frivolity.', '2015-04-08 07:11:42.000000', NULL, 1),
(7339428, 1146690, 100393, '<td valign="top">Great height you have here, like a mountain for the bike. The timing to bring the bike and shadow together brings a lot.</td>', 'Great height you have here, like a mountain for the bike. The timing to bring the bike and shadow together brings a lot.', '2015-04-08 07:12:38.000000', NULL, 1),
(7339429, 1146708, 100393, '<td valign="top">Interesting apparent solarisation. A nice dog too (I''m a sucker for the beasts).<br/> <br/>I enjoy how the fur is making inroads into the walker''s leg.</td>', 'Interesting apparent solarisation. A nice dog too (I''m a sucker for the beasts). I enjoy how the fur is making inroads into the walker''s leg.', '2015-04-08 07:13:38.000000', NULL, 1),
(7339430, 1146591, 100393, '<td valign="top">The subtle ripples make the image for me - like footfall induced micro-tremors!</td>', 'The subtle ripples make the image for me - like footfall induced micro-tremors!', '2015-04-08 07:14:23.000000', NULL, 1),
(7339431, 1146271, 100393, '<td valign="top">An exercise in geometric composition. I think I''d have liked still bolder shadows, bit I like where your head is at with this shot.</td>', 'An exercise in geometric composition. I think I''d have liked still bolder shadows, bit I like where your head is at with this shot.', '2015-04-08 07:15:23.000000', NULL, 1),
(7339432, 1146705, 100393, '<td valign="top">I enjoy the contrast, it brings about just the sense of dusk (or duks) that your title proclaims.<br/> <br/>A bit straight-up for me but nicely presented nonetheless.</td>', 'I enjoy the contrast, it brings about just the sense of dusk (or duks) that your title proclaims. A bit straight-up for me but nicely presented nonetheless.', '2015-04-08 07:16:56.000000', NULL, 1),
(7339433, 1146720, 100393, '<td valign="top">In some ways a strange shot for this challenge but is I look at it as a photograph (as a discrete artefact) as opposed to the outcome of a process, I can begin to appreciate it a bit more.<br/> <br/>The consistent and deep cyan background is very effective like a mounting background - your subject indeed floats within in it like a transient interloper.</td>', 'In some ways a strange shot for this challenge but is I look at it as a photograph (as a discrete artefact) as opposed to the outcome of a process, I can begin to appreciate it a bit more. The consistent and deep cyan background is very effective like a mounting background - your subject indeed floats within in it like a transient interloper.', '2015-04-08 07:19:34.000000', NULL, 1),
(7339434, 1146298, 100393, '<td valign="top">A canopy-scape? Quite interesting - as much for what is not there as well as what is.</td>', 'A canopy-scape? Quite interesting - as much for what is not there as well as what is.', '2015-04-08 07:20:17.000000', NULL, 1),
(7339435, 1145810, 100393, '<td valign="top">An image with some potential but your vision appears to be held back by a somewhat crunchy rendition and an inhibited contrast profile. I do like what you''ve captured of the girls though and how we get a glimpse into their joy of the day.</td>', 'An image with some potential but your vision appears to be held back by a somewhat crunchy rendition and an inhibited contrast profile. I do like what you''ve captured of the girls though and how we get a glimpse into their joy of the day.', '2015-04-08 07:22:27.000000', NULL, 1),
(7339436, 1146563, 100393, '<td valign="top">A cyclops eye - I do like that. Foliage though is a tricky beast, especially in colour. I struggle enjoying that part of it. Give me this in a square crop with a centred eye and a monochrome presentation and I think I''d be sold. But then, it wouldn''t be this image and that wouldn''t be fair.</td>', 'A cyclops eye - I do like that. Foliage though is a tricky beast, especially in colour. I struggle enjoying that part of it. Give me this in a square crop with a centred eye and a monochrome presentation and I think I''d be sold. But then, it wouldn''t be this image and that wouldn''t be fair.', '2015-04-08 07:24:33.000000', NULL, 1),
(7339437, 1146648, 100393, '<td valign="top">Interesting visual pun. I like the limited colour palette too. The thin vignette/frame is I think a little prominent, but I like the sense of curvature it gives to the lefthand side of the image.</td>', 'Interesting visual pun. I like the limited colour palette too. The thin vignette/frame is I think a little prominent, but I like the sense of curvature it gives to the lefthand side of the image.', '2015-04-08 07:26:01.000000', NULL, 1),
(7339438, 1146361, 100393, '<td valign="top">Amusing juxtaposition, I like how how have communicated a clear message within such a tight composition. You''ve done this so effectively that you title is redundant. That''s an accomplishment in itself.</td>', 'Amusing juxtaposition, I like how how have communicated a clear message within such a tight composition. You''ve done this so effectively that you title is redundant. That''s an accomplishment in itself.', '2015-04-08 07:27:25.000000', NULL, 1),
(7339439, 1146717, 100393, '<td valign="top">Like the electric which on the ned (also in this challenge) I feel I am being toyed with here - invited to attempt to finding meaning amidst random juxtaposition. It is well made though, lovely tones and well judged pseudo-grain.</td>', 'Like the electric which on the ned (also in this challenge) I feel I am being toyed with here - invited to attempt to finding meaning amidst random juxtaposition. It is well made though, lovely tones and well judged pseudo-grain.', '2015-04-08 07:29:11.000000', NULL, 1),
(7339440, 1146543, 100393, '<td valign="top">Goodness, where did you find those? It took me a while to get the yellow brick road reference so distracted was I by the bling of the shoes.<br/> <br/>I appreciate the level of construction of concept here.</td>', 'Goodness, where did you find those? It took me a while to get the yellow brick road reference so distracted was I by the bling of the shoes. I appreciate the level of construction of concept here.', '2015-04-08 07:30:51.000000', NULL, 1),
(7339441, 1146057, 100393, '<td valign="top">Goodness, and people think my work can be a bit racy!<br/> <br/>Strange choice of image but I like that you''ve gone with this, just from a form and structure perspective it has some inherent interest.</td>', 'Goodness, and people think my work can be a bit racy! Strange choice of image but I like that you''ve gone with this, just from a form and structure perspective it has some inherent interest.', '2015-04-08 07:32:57.000000', NULL, 1),
(7339442, 1146636, 100393, '<td valign="top">Perhaps too balanced a composition, I wish it were a little more disruptive. It is intriguing how the longer you look at the image, the harder it is for your eyes to focus. Quite a trick.</td>', 'Perhaps too balanced a composition, I wish it were a little more disruptive. It is intriguing how the longer you look at the image, the harder it is for your eyes to focus. Quite a trick.', '2015-04-08 07:35:06.000000', NULL, 1),
(7339443, 1146467, 100393, '<td valign="top">A capable shot of an endearing scene. I can feel the crispness of the air.</td>', 'A capable shot of an endearing scene. I can feel the crispness of the air.', '2015-04-08 07:35:50.000000', NULL, 1),
(7339444, 1146531, 100393, '<td valign="top">I think trees and crunchy foliage are tricky to shoot and present - too much contrast and the complexity of form is lost, too little and the subtleties are there but inadequately captured in the dynamic ranges of most images. My personal issues with photographing trees mean that I''m not as receptive to this image as others may be.</td>', 'I think trees and crunchy foliage are tricky to shoot and present - too much contrast and the complexity of form is lost, too little and the subtleties are there but inadequately captured in the dynamic ranges of most images. My personal issues with photographing trees mean that I''m not as receptive to this image as others may be.', '2015-04-08 07:38:05.000000', NULL, 1),
(7339445, 1146168, 100393, '<td valign="top">A bit straight up for me. I do like the beheaded crop but long for a bit more photographic interest.</td>', 'A bit straight up for me. I do like the beheaded crop but long for a bit more photographic interest.', '2015-04-08 07:39:09.000000', NULL, 1),
(7339446, 1146299, 100393, '<td valign="top">Darkness indeed. As an object, a study of dark, shade, little light and blur, I can see where the origins of this lie. But, as a communication act between me and it - there is little here for me to converse with. That''s fine as an intent and I suspect it has been brought into being by a photographic sophisticate, but for me, I''m left with little.</td>', 'Darkness indeed. As an object, a study of dark, shade, little light and blur, I can see where the origins of this lie. But, as a communication act between me and it - there is little here for me to converse with. That''s fine as an intent and I suspect it has been brought into being by a photographic sophisticate, but for me, I''m left with little.', '2015-04-08 07:43:22.000000', NULL, 1),
(7339447, 1146222, 100393, '<td valign="top">A capable macro shot, no doubt about that. I really enjoy the overlapping circles of confusion top right but mainly pictures of objects don''t pus my buttons.</td>', 'A capable macro shot, no doubt about that. I really enjoy the overlapping circles of confusion top right but mainly pictures of objects don''t pus my buttons.', '2015-04-08 07:44:41.000000', NULL, 1),
(7339448, 1146444, 100393, '<td valign="top">I do like the red tassel, but for me it isn''t enough for me to get over my prejudice of photos of statues (or ornaments) - I just like to see something that has more of the photographer than the original artist within it.</td>', 'I do like the red tassel, but for me it isn''t enough for me to get over my prejudice of photos of statues (or ornaments) - I just like to see something that has more of the photographer than the original artist within it.', '2015-04-08 07:46:26.000000', NULL, 1),
(7339449, 1146715, 100393, '<td valign="top">Nice gentle blurring and a comfortable limited palette. Perhaps not enough here for me, but I think you''ve executed a particular vision really well.</td>', 'Nice gentle blurring and a comfortable limited palette. Perhaps not enough here for me, but I think you''ve executed a particular vision really well.', '2015-04-08 07:47:15.000000', NULL, 1),
(7339450, 1145883, 100393, '<td valign="top">What to say here? I think trees, branches and foliage is just so difficult to photograph. I avoid the stuff now - I just can''t pull it off. My prejudice leaves me somewhat unable to engage with your image - I note and respect your choices but for me a narrow DOF doesn''t work, nor would a deep one...<br/> <br/>Just such a hard subject to get to work. Trees - they leave you nowhere to go.</td>', 'What to say here? I think trees, branches and foliage is just so difficult to photograph. I avoid the stuff now - I just can''t pull it off. My prejudice leaves me somewhat unable to engage with your image - I note and respect your choices but for me a narrow DOF doesn''t work, nor would a deep one... Just such a hard subject to get to work. Trees - they leave you nowhere to go.', '2015-04-08 07:51:03.000000', NULL, 1),
(7339451, 1146628, 100393, '<td valign="top">I like the apparent blasts of burning gas left and right but the target banding is problematic for me. The central object is intriguing, particularly the way it is perched upon the stand but overall I think it''s a hard picture to relate to.</td>', 'I like the apparent blasts of burning gas left and right but the target banding is problematic for me. The central object is intriguing, particularly the way it is perched upon the stand but overall I think it''s a hard picture to relate to.', '2015-04-08 07:52:58.000000', NULL, 1),
(7339453, 1146484, 100393, '<td valign="top">Limited in its construction - that''s a good thing - it feels tight and deliberately constrained, like I can feel your photographic influence on the scene. I like that your choices are so apparent.</td>', 'Limited in its construction - that''s a good thing - it feels tight and deliberately constrained, like I can feel your photographic influence on the scene. I like that your choices are so apparent.', '2015-04-08 07:54:23.000000', NULL, 1),
(7339470, 1146267, 30364, '<td valign="top">Interesting to me mostly because of the symbolism of the headless ideals in the glamour gowns versus the captivated young lady observer who seems to be dressed modestly and conservatively. I wonder does the absence of heads make it easier for the observer to mentally project themselves into the gowns?  Sort of a virtual trying-on?  Probably it does.<br/> <br/>It''s also an interesting photograph because it''s so harsh; the colours (of the gowns) are so uncompromising, and the lighting of the window so artlessly direct.  A sort of beauty through bluntness, much like I''d imagine are the customers who''d buy such gowns, and the places they''d wear them.  Thank you.</td>', 'Interesting to me mostly because of the symbolism of the headless ideals in the glamour gowns versus the captivated young lady observer who seems to be dressed modestly and conservatively. I wonder does the absence of heads make it easier for the observer to mentally project themselves into the gowns?  Sort of a virtual trying-on?  Probably it does. It''s also an interesting photograph because it''s so harsh; the colours (of the gowns) are so uncompromising, and the lighting of the window so artlessly direct.  A sort of beauty through bluntness, much like I''d imagine are the customers who''d buy such gowns, and the places they''d wear them.  Thank you.', '2015-04-08 08:50:14.000000', NULL, 1),
(7339475, 1146288, 30364, '<td valign="top">Oh, here''s a twist (for me).  I''m surrounded by zebras every day, but mine are all Burchell''s or plains zebras.  These are something else; I think they''re Grevy''s zebras.  Anyway, stripey buggers that I once heard a child call "pyjama horses", which I think would be a good official name.<br/> <br/>I like your processing because it makes the picture seem like an illustration from a 19th century travel book (and I love reading those!)  Given the vegetation visible this must surely be in a zoo, but if so you''ve done a good job making it look natural.<br/> <br/>Thank you.</td>', 'Oh, here''s a twist (for me).  I''m surrounded by zebras every day, but mine are all Burchell''s or plains zebras.  These are something else; I think they''re Grevy''s zebras.  Anyway, stripey buggers that I once heard a child call "pyjama horses", which I think would be a good official name. I like your processing because it makes the picture seem like an illustration from a 19th century travel book (and I love reading those!)  Given the vegetation visible this must surely be in a zoo, but if so you''ve done a good job making it look natural. Thank you.', '2015-04-08 09:01:12.000000', NULL, 1),
(7339476, 1145712, 30364, '<td valign="top">So weird and inexplicable.  I love that.  There must be a reason that Linking Park listeners use a mixer rather than earphones, but as I''m not one it escapes me.  Your picture is an in joke, I think, but that''s cool with me because nearly all mine are in jokes too. Extra point for the vignette, and thank you.</td>', 'So weird and inexplicable.  I love that.  There must be a reason that Linking Park listeners use a mixer rather than earphones, but as I''m not one it escapes me.  Your picture is an in joke, I think, but that''s cool with me because nearly all mine are in jokes too. Extra point for the vignette, and thank you.', '2015-04-08 09:06:03.000000', NULL, 1),
(7339477, 1146476, 30364, '<td valign="top">Absolutely cannot look at this and not smile.  Of how many photographs can that be said?  Precious few.  That''s why they''re precious.  Thank you.</td>', 'Absolutely cannot look at this and not smile.  Of how many photographs can that be said?  Precious few.  That''s why they''re precious.  Thank you.', '2015-04-08 09:07:41.000000', NULL, 1),
(7339482, 1146411, 30364, '<td valign="top">Nicely uncertain, with the foreground grass and the even light making it authentically environmental rather than an unequivocal zoo-style portrait.  You <i>feel</i> something about the critter, when it''s photographed like this.  It''s a deer of some kind presumably?  Looks a lot like a female waterbuck though.  Anyway I like environmental wildlife pictures, so than you.</td>', 'Nicely uncertain, with the foreground grass and the even light making it authentically environmental rather than an unequivocal zoo-style portrait.  You feel something about the critter, when it''s photographed like this.  It''s a deer of some kind presumably?  Looks a lot like a female waterbuck though.  Anyway I like environmental wildlife pictures, so than you.', '2015-04-08 09:11:01.000000', NULL, 1),
(7339485, 1146658, 30364, '<td valign="top">Awesome!  What a juxtaposition!  I almost never say <i>what I''d have done</i> (what do I know?) but as the exception that proves the rule I''d have eased back on the peripheral blur, just a wee bit.  But this is more than a once-in-a-lifetime shot opportunity, and you have done a great job of it.  Thank you.</td>', 'Awesome!  What a juxtaposition!  I almost never say what I''d have done (what do I know?) but as the exception that proves the rule I''d have eased back on the peripheral blur, just a wee bit.  But this is more than a once-in-a-lifetime shot opportunity, and you have done a great job of it.  Thank you.', '2015-04-08 09:13:30.000000', NULL, 1),
(7339493, 1146717, 30364, '<td valign="top">That''s funny, although probably I''m the only one who gets the reference.  All my favourite stuff is there: grain, gloomy mood, dark dark corners, and a WTF combination.  I got a welcome chuckle out of this, and I thank you.</td>', 'That''s funny, although probably I''m the only one who gets the reference.  All my favourite stuff is there: grain, gloomy mood, dark dark corners, and a WTF combination.  I got a welcome chuckle out of this, and I thank you.', '2015-04-08 09:25:53.000000', NULL, 1),
(7339497, 1146463, 30364, '<td valign="top">Remarkable shot!  And I love all those street marks, especially with the drive-through smears and the puzzling U-turn marks where a bike (or two) have had a wise second thought about the deluge.The lemon yellow portal at upper right appears to be Batman''s place.  So this must be Gotham?  It''s great fun, and lovely to look at too.  Thank you.</td>', 'Remarkable shot!  And I love all those street marks, especially with the drive-through smears and the puzzling U-turn marks where a bike (or two) have had a wise second thought about the deluge.The lemon yellow portal at upper right appears to be Batman''s place.  So this must be Gotham?  It''s great fun, and lovely to look at too.  Thank you.', '2015-04-08 09:31:53.000000', NULL, 1),
(7339501, 1146458, 30364, '<td valign="top">Interesting urban tableau.  The interesting-looking guy (?) at right is wearing a heart locket, and Salman Rushdie is reading the paper at left (and holding it so close he really should consider that SpecSavers deal on the back page).  Can''t ask for much more cafe theatre than this.  Plus some grain for seasoning.  Thank you.</td>', 'Interesting urban tableau.  The interesting-looking guy (?) at right is wearing a heart locket, and Salman Rushdie is reading the paper at left (and holding it so close he really should consider that SpecSavers deal on the back page).  Can''t ask for much more cafe theatre than this.  Plus some grain for seasoning.  Thank you.', '2015-04-08 09:36:36.000000', NULL, 1),
(7339505, 1146054, 30364, '<td valign="top">That''s very nice; the apt accidental juxtaposition is great fun, but what I like most is the wires, which look like someone has scribbled disapproving lines through the whole thing.  Not me though; I approve.  Thank you.</td>', 'That''s very nice; the apt accidental juxtaposition is great fun, but what I like most is the wires, which look like someone has scribbled disapproving lines through the whole thing.  Not me though; I approve.  Thank you.', '2015-04-08 09:39:49.000000', NULL, 1),
(7339508, 1146703, 30364, '<td valign="top">Lovely moment of companionship.  I know you intentionally went all loose for the challenge, but I reckon it works better with the bit of negligence anyway.  I see all that''s important like this, and tack sharp focus would have detracted rather than added.  Thank you.</td>', 'Lovely moment of companionship.  I know you intentionally went all loose for the challenge, but I reckon it works better with the bit of negligence anyway.  I see all that''s important like this, and tack sharp focus would have detracted rather than added.  Thank you.', '2015-04-08 09:42:34.000000', NULL, 1),
(7339513, 1146563, 30364, '<td valign="top">My goodness that is a striking bird!  Hope you will say what it is in your notes.  It''s good (for me at least) to not see the whole thing, because it allows some speculation about the obscured bits.  I''m trying to imagine the beak shape.  Nope, I got nothin''.  No bad thing.  Thank you.</td>', 'My goodness that is a striking bird!  Hope you will say what it is in your notes.  It''s good (for me at least) to not see the whole thing, because it allows some speculation about the obscured bits.  I''m trying to imagine the beak shape.  Nope, I got nothin''.  No bad thing.  Thank you.', '2015-04-08 09:47:01.000000', NULL, 1),
(7339543, 1146473, 114285, '<td valign="top">I nearly didn''t spot that elephant...a play on words with one of Paul''s past images. A very clever image. Already voted.</td>', 'I nearly didn''t spot that elephant...a play on words with one of Paul''s past images. A very clever image. Already voted.', '2015-04-08 10:58:19.000000', NULL, 1),
(7339544, 1146403, 114285, '<td valign="top">Superbly composed and edited.</td>', 'Superbly composed and edited.', '2015-04-08 10:59:27.000000', NULL, 1),
(7339545, 1146472, 114285, '<td valign="top">I''ve seen that tree before.</td>', 'I''ve seen that tree before.', '2015-04-08 11:00:01.000000', NULL, 1),
(7339546, 1146634, 114285, '<td valign="top">This is too good to be true. I predict the yellow for you, what else ;--)</td>', 'This is too good to be true. I predict the yellow for you, what else ;--)', '2015-04-08 11:01:02.000000', NULL, 1),
(7339547, 1146658, 114285, '<td valign="top">What a champion, congrats to both of them.</td>', 'What a champion, congrats to both of them.', '2015-04-08 11:01:34.000000', NULL, 1),
