(7339554, 1146598, 114285, '<td valign="top">I see the car window wiper pattern, a very strange and wonderful image, he looks like you caught him doing something. TT.</td>', 'I see the car window wiper pattern, a very strange and wonderful image, he looks like you caught him doing something. TT.', '2015-04-08 11:06:50.000000', NULL, 1),
(7339562, 1146460, 114285, '<td valign="top">I love the title, Paul would remember this wonderful movie.<br/> <br/>Your boy has a look of wonder and innocence all mixed in one, in my top 5.<br/> <br/>8</td>', 'I love the title, Paul would remember this wonderful movie. Your boy has a look of wonder and innocence all mixed in one, in my top 5. 8', '2015-04-08 11:22:31.000000', NULL, 1),
