(7339627, 1146626, 113411, '<td valign="top">This is too fabulous, the tilt, the grain, the Gonzo accessories are perfection. You have captured Ubique so well!</td>', 'This is too fabulous, the tilt, the grain, the Gonzo accessories are perfection. You have captured Ubique so well!', '2015-04-08 13:33:54.000000', NULL, 1),
(7339630, 1145715, 113411, '<td valign="top">Great tribute! The lines, the pov and the high contrast processing are perfect. A tilt would have been a slam dunk!</td>', 'Great tribute! The lines, the pov and the high contrast processing are perfect. A tilt would have been a slam dunk!', '2015-04-08 13:37:12.000000', NULL, 1),
(7339634, 1146460, 113411, '<td valign="top">this is wonderful. The body language and expression are a total enigma and open to a lot of interpretation.<br/>I love the way it is processed.. a great tribute to Ubique.</td>', 'this is wonderful. The body language and expression are a total enigma and open to a lot of interpretation.I love the way it is processed.. a great tribute to Ubique.', '2015-04-08 13:40:24.000000', NULL, 1),
(7339639, 1146543, 113411, '<td valign="top">This is great ..just enough affectation and enigma to pay tribute to the philosophy of Ubique. The red shoes, pov and<br/>composition, brilliant!</td>', 'This is great ..just enough affectation and enigma to pay tribute to the philosophy of Ubique. The red shoes, pov andcomposition, brilliant!', '2015-04-08 13:43:53.000000', NULL, 1),
(7339660, 1146564, 113411, '<td valign="top">What a perfect tribute to Ubique. The composition is perfect. I hope the dog is alive and well and was just<br/>posing.</td>', 'What a perfect tribute to Ubique. The composition is perfect. I hope the dog is alive and well and was justposing.', '2015-04-08 14:06:30.000000', NULL, 1),
(7339668, 1146591, 124815, '<td valign="top">evocative of this long winter</td>', 'evocative of this long winter', '2015-04-08 14:15:03.000000', NULL, 1),
(7339686, 1146528, 138630, '<td valign="top">Contrasts.  Starkly inanimate w/ warmly human.  Dark w/ light.  Linear w/ curves.  I regret the very strong vignette at the top.  Wonderful for both design elements and story suggestions.</td>', 'Contrasts.  Starkly inanimate w/ warmly human.  Dark w/ light.  Linear w/ curves.  I regret the very strong vignette at the top.  Wonderful for both design elements and story suggestions.', '2015-04-08 14:40:08.000000', NULL, 1),
