(7339742, 1146711, 113411, '<td valign="top">How fabulous! A good tribute to Ubique. It looks authentic and spontaneous and the framing and processing is perfect. I love it.</td>', 'How fabulous! A good tribute to Ubique. It looks authentic and spontaneous and the framing and processing is perfect. I love it.', '2015-04-08 16:17:22.000000', NULL, 1),
(7339750, 1146598, 113411, '<td valign="top">This is a good tribute to Ubique. Just enough enigma and affectation to make it interesting. The composition is wonderful..and shooting it behind glass with drops on the glass really works. Well done!</td>', 'This is a good tribute to Ubique. Just enough enigma and affectation to make it interesting. The composition is wonderful..and shooting it behind glass with drops on the glass really works. Well done!', '2015-04-08 16:26:28.000000', NULL, 1),
