(7339753, 1146239, 113411, '<td valign="top">Great Ubique tribute..the framing, blur and just enough enigma to keep it interesting!</td>', 'Great Ubique tribute..the framing, blur and just enough enigma to keep it interesting!', '2015-04-08 16:30:02.000000', NULL, 1),
