(7339909, 1146591, 159132, '<td valign="top">So stark as to be disorienting. The wavelets in the puddle are beautiful; they are suggestive of the grain in the leather</td>', 'So stark as to be disorienting. The wavelets in the puddle are beautiful; they are suggestive of the grain in the leather', '2015-04-09 01:17:41.000000', NULL, 1),
(7339910, 1145853, 159132, '<td valign="top">This gives me faith that there really are an infinite number of universes</td>', 'This gives me faith that there really are an infinite number of universes', '2015-04-09 01:19:43.000000', NULL, 1),
(7339911, 1146233, 159132, '<td valign="top">How can birds look so nonchalant when they are flying? Don''t they understand what a feat they are accomplishing? This main character looks like it is auditioning for a part in the The Wizard of Oz.</td>', 'How can birds look so nonchalant when they are flying? Don''t they understand what a feat they are accomplishing? This main character looks like it is auditioning for a part in the The Wizard of Oz.', '2015-04-09 01:22:12.000000', NULL, 1),
(7339913, 1146662, 138630, '<td valign="top">of the past?  This has a prehistoric feel</td>', 'of the past?  This has a prehistoric feel', '2015-04-09 01:31:04.000000', NULL, 1),
(7339915, 1146531, 30982, '<td valign="top">Lovely pastoral scene, quietly normal.  I''m waiting for something to jump out from the side when I least expect it....</td>', 'Lovely pastoral scene, quietly normal.  I''m waiting for something to jump out from the side when I least expect it....', '2015-04-09 02:24:40.000000', NULL, 1),
