(7341102, 1146249, 113156, '<td valign="top">I see a Rastafarian in the dunes on a bike coming home with the shopping but I could be wrong :-) I do like it though.</td>', 'I see a Rastafarian in the dunes on a bike coming home with the shopping but I could be wrong :-) I do like it though.', '2015-04-11 14:34:55.000000', NULL, 1),
(7341103, 1146364, 113591, '<td valign="top">I also like to take photo''s of photographers in action. The rickety structure makes the image very interesting. Pity about the blank screen.</td>', 'I also like to take photo''s of photographers in action. The rickety structure makes the image very interesting. Pity about the blank screen.', '2015-04-11 14:35:05.000000', NULL, 1),
(7341104, 1146168, 113591, '<td valign="top">Right. We really have so little choice - kick this one or kick that one, but it confuses us so easily.</td>', 'Right. We really have so little choice - kick this one or kick that one, but it confuses us so easily.', '2015-04-11 14:37:17.000000', NULL, 1),
