(7343635, 1146472, 68504, '<td valign="top">so satisfying that you give prominence to the roots. a thoughtful essay.</td>', 'so satisfying that you give prominence to the roots. a thoughtful essay.', '2015-04-19 21:11:06.000000', NULL, 0),
(7350431, 1146434, 41337, '<td valign="top">I''m pretty sure you could have shot this perfectly in focus and in full color and in high definition, but much like the insects you see stuck inside panes of glass hanging on someone''s wall, the end result would be rather static and lifeless. It would only serve as a trophy, a means of promoting oneself. Not this. This is different. It has tension. Everything from the slight blur of the wings to the off-kilter position of the butterfly and the fountain of bokeh in the background screams it. There''s anticipation here, a flight not yet flown. This is not some trophy to mount on one''s mantle. No, it''s an affirmation, an appreciation of life.<br/><br/><i>Message edited by author 2015-05-14 02:54:37.</i></td>', 'I''m pretty sure you could have shot this perfectly in focus and in full color and in high definition, but much like the insects you see stuck inside panes of glass hanging on someone''s wall, the end result would be rather static and lifeless. It would only serve as a trophy, a means of promoting oneself. Not this. This is different. It has tension. Everything from the slight blur of the wings to the off-kilter position of the butterfly and the fountain of bokeh in the background screams it. There''s anticipation here, a flight not yet flown. This is not some trophy to mount on one''s mantle. No, it''s an affirmation, an appreciation of life.', '2015-05-14 03:53:50.000000', '2015-05-14 03:54:37.000000', 0),
(7356932, 1146708, 76335, '<td valign="top">Nice. Seems to be peeling off of the frame.</td>', 'Nice. Seems to be peeling off of the frame.', '2015-06-03 12:51:33.000000', NULL, 0),
(7357273, 1146708, 74588, '<td valign="top">oh,boy</td>', 'oh,boy', '2015-06-04 16:08:10.000000', NULL, 0),
